    "/advisories": {
      "get": {
        "summary": "List global security advisories",
        "description": "Lists all global security advisories that match the specified parameters. If no other parameters are defined, the request will return only GitHub-reviewed advisories that are not malware.\n\nBy default, all responses will exclude advisories for malware, because malware are not standard vulnerabilities. To list advisories for malware, you must include the `type` parameter in your request, with the value `malware`. For more information about the different types of security advisories, see \"[About the GitHub Advisory database](https://docs.github.com/code-security/security-advisories/global-security-advisories/about-the-github-advisory-database#about-types-of-security-advisories).\"",
        "tags": [
          "security-advisories"
        ],
        "operationId": "security-advisories/list-global-advisories",
        "externalDocs": {
          "description": "API method documentation",
          "url": "https://docs.github.com/rest/security-advisories/global-advisories#list-global-security-advisories"
        },
        "parameters": [
          {
            "name": "ghsa_id",
            "in": "query",
            "description": "If specified, only advisories with this GHSA (GitHub Security Advisory) identifier will be returned.",
            "schema": {
              "type": "string"
            }
          },
          {
            "name": "type",
            "in": "query",
            "description": "If specified, only advisories of this type will be returned. By default, a request with no other parameters defined will only return reviewed advisories that are not malware.",
            "schema": {
              "type": "string",
              "enum": [
                "reviewed",
                "malware",
                "unreviewed"
              ],
              "default": "reviewed"
            }
          },
          {
            "name": "cve_id",
            "description": "If specified, only advisories with this CVE (Common Vulnerabilities and Exposures) identifier will be returned.",
            "in": "query",
            "schema": {
              "type": "string"
            }
          },
          {
            "name": "ecosystem",
            "in": "query",
            "description": "If specified, only advisories for these ecosystems will be returned.",
            "schema": {
              "$ref": "#/components/schemas/security-advisory-ecosystems"
            }
          },
          {
            "name": "severity",
            "in": "query",
            "description": "If specified, only advisories with these severities will be returned.",
            "schema": {
              "type": "string",
              "enum": [
                "unknown",
                "low",
                "medium",
                "high",
                "critical"
              ]
            }
          },
          {
            "name": "cwes",
            "in": "query",
            "description": "If specified, only advisories with these Common Weakness Enumerations (CWEs) will be returned.\n\nExample: `cwes=79,284,22` or `cwes[]=79&cwes[]=284&cwes[]=22`",
            "schema": {
              "oneOf": [
                {
                  "type": "string"
                },
                {
                  "type": "array",
                  "items": {
                    "type": "string"
                  }
                }
              ]
            }
          },
          {
            "name": "is_withdrawn",
            "in": "query",
            "description": "Whether to only return advisories that have been withdrawn.",
            "schema": {
              "type": "boolean"
            }
          },
          {
            "name": "affects",
            "in": "query",
            "description": "If specified, only return advisories that affect any of `package` or `package@version`. A maximum of 1000 packages can be specified.\nIf the query parameter causes the URL to exceed the maximum URL length supported by your client, you must specify fewer packages.\n\nExample: `affects=package1,package2@1.0.0,package3@2.0.0` or `affects[]=package1&affects[]=package2@1.0.0`",
            "schema": {
              "oneOf": [
                {
                  "type": "string"
                },
                {
                  "type": "array",
                  "maxItems": 1000,
                  "items": {
                    "type": "string"
                  }
                }
              ]
            }
          },
          {
            "name": "published",
            "in": "query",
            "description": "If specified, only return advisories that were published on a date or date range.\n\nFor more information on the syntax of the date range, see \"[Understanding the search syntax](https://docs.github.com/search-github/getting-started-with-searching-on-github/understanding-the-search-syntax#query-for-dates).\"",
            "schema": {
              "type": "string"
            }
          },
          {
            "name": "updated",
            "in": "query",
            "description": "If specified, only return advisories that were updated on a date or date range.\n\nFor more information on the syntax of the date range, see \"[Understanding the search syntax](https://docs.github.com/search-github/getting-started-with-searching-on-github/understanding-the-search-syntax#query-for-dates).\"",
            "schema": {
              "type": "string"
            }
          },
          {
            "name": "modified",
            "description": "If specified, only show advisories that were updated or published on a date or date range.\n\nFor more information on the syntax of the date range, see \"[Understanding the search syntax](https://docs.github.com/search-github/getting-started-with-searching-on-github/understanding-the-search-syntax#query-for-dates).\"",
            "in": "query",
            "schema": {
              "type": "string"
            }
          },
          {
            "name": "epss_percentage",
            "in": "query",
            "description": "If specified, only return advisories that have an EPSS percentage score that matches the provided value.\nThe EPSS percentage represents the likelihood of a CVE being exploited.",
            "schema": {
              "type": "string"
            }
          },
          {
            "name": "epss_percentile",
            "in": "query",
            "description": "If specified, only return advisories that have an EPSS percentile score that matches the provided value.\nThe EPSS percentile represents the relative rank of the CVE's likelihood of being exploited compared to other CVEs.",
            "schema": {
              "type": "string"
            }
          },
          {
            "$ref": "#/components/parameters/pagination-before"
          },
          {
            "$ref": "#/components/parameters/pagination-after"
          },
          {
            "$ref": "#/components/parameters/direction"
          },
          {
            "name": "per_page",
            "description": "The number of results per page (max 100). For more information, see \"[Using pagination in the REST API](https://docs.github.com/rest/using-the-rest-api/using-pagination-in-the-rest-api).\"",
            "in": "query",
            "schema": {
              "type": "integer",
              "minimum": 1,
              "maximum": 100,
              "default": 30
            }
          },
          {
            "name": "sort",
            "description": "The property to sort the results by.",
            "in": "query",
            "required": false,
            "schema": {
              "type": "string",
              "enum": [
                "updated",
                "published",
                "epss_percentage",
                "epss_percentile"
              ],
              "default": "published"
            }
          }
        ],
        "responses": {
          "200": {
            "description": "Response",
            "content": {
              "application/json": {
                "schema": {
                  "type": "array",
                  "items": {
                    "$ref": "#/components/schemas/global-advisory"
                  }
                },
                "examples": {
                  "default": {
                    "$ref": "#/components/examples/global-advisory-items"
                  }
                }
              }
            }
          },
          "429": {
            "description": "Too many requests",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/basic-error"
                }
              }
            }
          },
          "422": {
            "$ref": "#/components/responses/validation_failed_simple"
          }
        },
        "x-github": {
          "githubCloudOnly": false,
          "enabledForGitHubApps": true,
          "category": "security-advisories",
          "subcategory": "global-advisories"
        }
      }
    },
    "/advisories/{ghsa_id}": {
      "get": {
        "summary": "Get a global security advisory",
        "description": "Gets a global security advisory using its GitHub Security Advisory (GHSA) identifier.",
        "tags": [
          "security-advisories"
        ],
        "operationId": "security-advisories/get-global-advisory",
        "externalDocs": {
          "description": "API method documentation",
          "url": "https://docs.github.com/rest/security-advisories/global-advisories#get-a-global-security-advisory"
        },
        "parameters": [
          {
            "$ref": "#/components/parameters/ghsa_id"
          }
        ],
        "responses": {
          "200": {
            "description": "Response",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/global-advisory"
                },
                "examples": {
                  "default": {
                    "$ref": "#/components/examples/global-advisory"
                  }
                }
              }
            }
          },
          "404": {
            "$ref": "#/components/responses/not_found"
          }
        },
        "x-github": {
          "githubCloudOnly": false,
          "enabledForGitHubApps": true,
          "category": "security-advisories",
          "subcategory": "global-advisories"
        }
      }
    },
    "/agents/automations": {
      "get": {
        "summary": "List automations for user",
        "description": "Returns automations whose `created_by` user is the authenticated caller, across\nrepositories the caller can read. This includes both user-owned and repository-owned\nautomations created by the caller but excludes repository-owned automations created by\nsomeone else even if the caller has write access to the repository.\n\nUse the repository-scoped list operation for those automations. The `owner_type` filter\nonly narrows this creator-scoped collection.\n\n**Fine-grained access tokens for \"List automations for user\"**\n\nThis endpoint works with the following fine-grained token types:\n\n* [GitHub App user access tokens](https://docs.github.com/en/apps/creating-github-apps/authenticating-with-a-github-app/generating-a-user-access-token-for-a-github-app)\n* [Fine-grained personal access tokens](https://docs.github.com/en/authentication/keeping-your-account-and-data-secure/managing-your-personal-access-tokens#creating-a-fine-grained-personal-access-token)\n\nThe fine-grained token must have one of the following permission sets for each\nrepository accessed by this request:\n\n* \"Agent tasks\" repository permissions (read)\n* \"Contents\" repository permissions (read)\n\nThe required permission set depends on each repository's Automation permission\nconfiguration.\n\nGitHub App installation access tokens are not supported for this endpoint.\n",
        "tags": [
          "agent-automations"
        ],
        "operationId": "agent-automations/list-automations",
        "externalDocs": {
          "description": "API method documentation",
          "url": "https://docs.github.com/rest/agent-automations/agent-automations#list-automations-for-user"
        },
        "x-github": {
          "githubCloudOnly": false,
          "enabledForGitHubApps": true,
          "category": "agent-automations",
          "subcategory": "agent-automations"
        },
        "parameters": [
          {
            "name": "page",
            "in": "query",
            "schema": {
              "type": "integer",
              "default": 1,
              "minimum": 1
            },
            "description": "The page number of the results to fetch."
          },
          {
            "name": "per_page",
            "in": "query",
            "schema": {
              "type": "integer",
              "default": 30,
              "minimum": 1,
              "maximum": 100
            },
            "description": "The number of results per page (max 100)."
          },
          {
            "name": "owner_type",
            "in": "query",
            "schema": {
              "type": "string",
              "enum": [
                "user",
                "repository"
              ]
            },
            "description": "Filter automations by owner type. `user` returns automations owned by their creator, `repository` returns automations owned by the repository. Omit to return both."
          }
        ],
        "responses": {
          "200": {
            "description": "Automations retrieved successfully",
            "headers": {
              "Link": {
                "description": "Pagination links",
                "schema": {
                  "type": "string"
                },
                "example": "<https://api.github.com/agents/automations?page=2&per_page=1&owner_type=user>; rel=\"next\", <https://api.github.com/agents/automations?page=1&per_page=1&owner_type=user>; rel=\"first\""
              }
            },
            "content": {
              "application/json": {
                "schema": {
                  "type": "array",
                  "items": {
                    "type": "object",
                    "description": "A summary representation of an automation including repository identity (used in cross-repository list responses).",
                    "required": [
                      "id",
                      "repository",
                      "name",
                      "created_at",
                      "updated_at",
                      "created_by"
                    ],
                    "properties": {
                      "id": {
                        "type": "string",
                        "description": "The unique identifier of the automation."
                      },
                      "repository": {
                        "type": "object",
                        "description": "Repository identity for an automation in cross-repository list responses.",
                        "required": [
                          "id",
                          "owner",
                          "name"
                        ],
                        "properties": {
                          "id": {
                            "type": "integer",
                            "format": "int64",
                            "description": "The unique identifier of the repository."
                          },
                          "owner": {
                            "type": "string",
                            "description": "The repository owner login."
                          },
                          "name": {
                            "type": "string",
                            "description": "The repository name."
                          }
                        }
                      },
                      "name": {
                        "type": "string",
                        "description": "The name of the automation."
                      },
                      "enabled": {
                        "type": "boolean",
                        "description": "Whether the automation is currently enabled."
                      },
                      "owner_type": {
                        "type": "string",
                        "enum": [
                          "user",
                          "repository"
                        ],
                        "description": "Who owns the automation. `user` keeps it private to its creator and its runs act as that user. `repository` makes it belong to the repository, visible to anyone with read access to the repository, and its runs act as the Copilot app rather than as a person.",
                        "readOnly": true
                      },
                      "write_scope": {
                        "type": "string",
                        "enum": [
                          "trigger",
                          "repository"
                        ],
                        "description": "Controls which repository resources a run may modify. `trigger` limits writes to the resource that started the run, when one exists, and resources created during the run; `repository` allows writes to any resource in the repository. Supported values: `trigger`, `repository`.",
                        "default": "trigger"
                      },
                      "require_actor_write_permission": {
                        "type": "boolean",
                        "description": "When true, event-triggered runs require the event actor to have repo write permission, even when the org's allow_read_access_triggers policy is enabled. Does not apply to interval-scheduled runs, which always run as the automation owner.",
                        "default": false
                      },
                      "model": {
                        "type": "string",
                        "description": "The model to use for sessions triggered by this automation. Omit to use the platform default."
                      },
                      "reasoning_effort": {
                        "type": "string",
                        "description": "The reasoning effort to use for sessions triggered by this automation. Omit or leave empty for no override. Currently supported values: `none`, `low`, `medium`, `high`, `xhigh`, `max`"
                      },
                      "triggers": {
                        "type": "object",
                        "additionalProperties": false,
                        "description": "Public trigger configuration keyed by stable public trigger identifier. Each trigger has a closed, trigger-specific configuration schema.",
                        "properties": {
                          "interval": {
                            "type": "object",
                            "additionalProperties": false,
                            "required": [
                              "cadence"
                            ],
                            "properties": {
                              "cadence": {
                                "type": "array",
                                "minItems": 1,
                                "uniqueItems": true,
                                "items": {
                                  "type": "string",
                                  "enum": [
                                    "hourly",
                                    "daily",
                                    "weekly"
                                  ]
                                },
                                "description": "One or more schedules on which the Automation runs."
                              },
                              "hour_utc": {
                                "type": "integer",
                                "minimum": 0,
                                "maximum": 23,
                                "description": "UTC hour anchor (0 through 23) for daily and weekly schedules. Omitted daily and weekly values default to `0` (midnight UTC)."
                              },
                              "day_of_week": {
                                "type": "integer",
                                "minimum": 0,
                                "maximum": 6,
                                "description": "UTC weekday anchor for weekly schedules, where `0` is Sunday and `6` is Saturday. Omitted weekly values default to Monday (`1`)."
                              },
                              "minute_utc": {
                                "type": "integer",
                                "enum": [
                                  0,
                                  15,
                                  30,
                                  45
                                ],
                                "default": 0,
                                "description": "UTC minute anchor for daily and weekly schedules. Omitted daily and weekly values default to `0`. Must be omitted whenever `cadence` includes `hourly`."
                              },
                              "write_scope": {
                                "type": "string",
                                "enum": [
                                  "trigger",
                                  "repository"
                                ],
                                "description": "Override the Automation `write_scope` for runs started by this trigger. If omitted, the automation's `write_scope` is used. Organization or repository policy may restrict the effective scope to `trigger`."
                              }
                            }
                          },
                          "issue_opened": {
                            "type": "object",
                            "additionalProperties": false,
                            "properties": {
                              "query": {
                                "type": "string",
                                "minLength": 1,
                                "description": "A GitHub issue or pull request search query."
                              },
                              "write_scope": {
                                "type": "string",
                                "enum": [
                                  "trigger",
                                  "repository"
                                ],
                                "description": "Override the Automation `write_scope` for runs started by this trigger. If omitted, the automation's `write_scope` is used. Organization or repository policy may restrict the effective scope to `trigger`."
                              }
                            }
                          },
                          "issue_labeled": {
                            "type": "object",
                            "additionalProperties": false,
                            "properties": {
                              "query": {
                                "type": "string",
                                "minLength": 1,
                                "description": "A GitHub issue or pull request search query."
                              },
                              "labels": {
                                "type": "array",
                                "uniqueItems": true,
                                "items": {
                                  "type": "string"
                                },
                                "description": "Label names matched case-insensitively against the label added by the event. Omit or use an empty array to match every added label."
                              },
                              "write_scope": {
                                "type": "string",
                                "enum": [
                                  "trigger",
                                  "repository"
                                ],
                                "description": "Override the Automation `write_scope` for runs started by this trigger. If omitted, the automation's `write_scope` is used. Organization or repository policy may restrict the effective scope to `trigger`."
                              }
                            }
                          },
