    "/agents/automations/available-tools": {
      "get": {
        "summary": "List available automation tools",
        "description": "Returns the tools available to the authenticated caller for use when creating or updating an automation.\n\n**Fine-grained access tokens for \"List available automation tools\"**\n\nThis endpoint works with the following fine-grained token types:\n\n* [GitHub App user access tokens](https://docs.github.com/en/apps/creating-github-apps/authenticating-with-a-github-app/generating-a-user-access-token-for-a-github-app)\n* [Fine-grained personal access tokens](https://docs.github.com/en/authentication/keeping-your-account-and-data-secure/managing-your-personal-access-tokens#creating-a-fine-grained-personal-access-token)\n\nThis endpoint does not require repository permissions.\n\nGitHub App installation access tokens are not supported for this endpoint.\n",
        "tags": [
          "agent-automations"
        ],
        "operationId": "agent-automations/list-available-automation-tools",
        "externalDocs": {
          "description": "API method documentation",
          "url": "https://docs.github.com/rest/agent-automations/agent-automations#list-available-automation-tools"
        },
        "x-github": {
          "githubCloudOnly": false,
          "enabledForGitHubApps": true,
          "category": "agent-automations",
          "subcategory": "agent-automations"
        },
        "responses": {
          "200": {
            "description": "Available automation tools retrieved successfully",
            "content": {
              "application/json": {
                "schema": {
                  "type": "array",
                  "items": {
                    "type": "object",
                    "additionalProperties": false,
                    "description": "A CMC-controlled presentation category for Automation tools. Clients must not depend on group identifiers, membership, or ordering remaining stable.",
                    "required": [
                      "id",
                      "title",
                      "tools"
                    ],
                    "properties": {
                      "id": {
                        "type": "string",
                        "description": "A presentation-category identifier controlled by CMC."
                      },
                      "title": {
                        "type": "string",
                        "description": "The human-readable group title."
                      },
                      "tools": {
                        "type": "array",
                        "description": "The tools currently presented in this group.",
                        "items": {
                          "type": "object",
                          "additionalProperties": false,
                          "description": "A tool that can be selected in an Automation.",
                          "required": [
                            "id",
                            "title",
                            "description"
                          ],
                          "properties": {
                            "id": {
                              "type": "string",
                              "description": "The exact tool identifier accepted by Automation create and edit requests. The catalog is authoritative and open-ended; clients must accept identifiers they have not seen before."
                            },
                            "title": {
                              "type": "string",
                              "description": "The human-readable tool title."
                            },
                            "description": {
                              "type": "string",
                              "description": "A short description of what the tool does."
                            },
                            "scope": {
                              "type": "string",
                              "enum": [
                                "read",
                                "write"
                              ],
                              "description": "The tool's behavior level. `read` tools only retrieve data. `write` tools can change data. This describes tool behavior, not a specific GitHub token permission."
                            }
                          }
                        }
                      }
                    }
                  }
                },
                "examples": {
                  "default": {
