        "description": "Returns a list of tasks triggered by the specified automation.\n\nUser-owned automation history is available only to its creator, while repository-owned automation\nhistory is available to anyone with read access to the repository. Deleted and unlisted tasks are excluded.\nTasks produced by private-session agents are excluded unless the caller created the task,\nis a task collaborator, or the task is shared.\n\n**Fine-grained access tokens for \"List tasks for an automation\"**\n\nThis endpoint works with the following fine-grained token types:\n\n* [GitHub App user access tokens](https://docs.github.com/en/apps/creating-github-apps/authenticating-with-a-github-app/generating-a-user-access-token-for-a-github-app)\n* [Fine-grained personal access tokens](https://docs.github.com/en/authentication/keeping-your-account-and-data-secure/managing-your-personal-access-tokens#creating-a-fine-grained-personal-access-token)\n\nThe fine-grained token must have one of the following permission sets for each\nrepository accessed by this request:\n\n* \"Agent tasks\" repository permissions (read)\n* \"Contents\" repository permissions (read)\n\nThe required permission set depends on each repository's Automation permission\nconfiguration.\n\nGitHub App installation access tokens are not supported for this endpoint.\n",
        "tags": [
          "agent-automations"
        ],
        "operationId": "agent-automations/list-automation-tasks",
        "externalDocs": {
          "description": "API method documentation",
          "url": "https://docs.github.com/rest/agent-automations/agent-automations#list-tasks-for-an-automation"
        },
        "x-github": {
          "githubCloudOnly": false,
          "enabledForGitHubApps": true,
          "category": "agent-automations",
          "subcategory": "agent-automations"
        },
        "parameters": [
          {
            "name": "automation_id",
            "in": "path",
            "required": true,
            "schema": {
              "type": "string"
            },
            "description": "The unique identifier of the automation."
          },
          {
            "name": "per_page",
            "in": "query",
            "schema": {
              "type": "integer",
              "default": 30,
              "minimum": 1,
              "maximum": 100
            },
            "description": "The number of results per page (max 100)."
          },
          {
            "name": "page",
            "in": "query",
            "schema": {
              "type": "integer",
              "default": 1,
              "minimum": 1
            },
            "description": "The page number of the results to fetch."
          },
          {
            "name": "sort",
            "in": "query",
            "schema": {
              "type": "string",
              "default": "updated_at",
              "enum": [
                "updated_at",
                "created_at"
              ]
            },
            "description": "The field to sort results by. Can be `updated_at` or `created_at`."
          },
          {
            "name": "direction",
            "in": "query",
            "schema": {
              "type": "string",
              "default": "desc",
              "enum": [
                "asc",
                "desc"
              ]
            },
            "description": "The direction to sort results. Can be `asc` or `desc`."
          },
          {
            "name": "state",
            "in": "query",
            "schema": {
              "type": "string"
            },
            "description": "Comma-separated list of task states to filter by. Can be any combination of: `queued`, `in_progress`, `completed`, `failed`, `idle`, `waiting_for_user`, `timed_out`, `cancelled`."
          },
          {
            "name": "is_archived",
            "in": "query",
            "schema": {
              "type": "boolean",
              "default": false
            },
            "description": "Filter by archived status. When `true`, returns only archived tasks. When `false` or omitted, returns only non-archived tasks. Defaults to `false`."
          }
        ],
        "responses": {
          "200": {
            "description": "Tasks retrieved successfully",
            "headers": {
              "Link": {
                "description": "Pagination links for the automation's task history.",
                "schema": {
                  "type": "string"
                },
                "example": "<https://api.github.com/agents/automations/a1b2c3d4-e5f6-7890-abcd-ef1234567890/tasks?page=2&per_page=1>; rel=\"next\", <https://api.github.com/agents/automations/a1b2c3d4-e5f6-7890-abcd-ef1234567890/tasks?page=1&per_page=1>; rel=\"first\""
              }
            },
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "description": "A page of tasks created by an automation.",
                  "required": [
                    "tasks"
                  ],
                  "properties": {
                    "tasks": {
                      "type": "array",
                      "items": {
                        "type": "object",
                        "required": [
                          "id",
                          "state",
                          "created_at"
                        ],
                        "properties": {
                          "id": {
                            "type": "string",
                            "description": "Unique task identifier"
                          },
                          "url": {
                            "type": "string",
                            "description": "API URL for this task"
                          },
                          "html_url": {
                            "type": "string",
                            "description": "Web URL for this task"
                          },
                          "name": {
                            "type": "string",
                            "description": "Human-readable name derived from the task prompt"
                          },
                          "creator": {
                            "oneOf": [
                              {
                                "type": "object",
                                "description": "A GitHub user",
                                "properties": {
                                  "id": {
                                    "type": "integer",
                                    "format": "int64",
                                    "description": "The unique identifier of the user"
                                  }
                                }
                              }
                            ],
                            "description": "The entity who created this task"
                          },
                          "creator_type": {
                            "type": "string",
                            "description": "Type of the task creator",
                            "enum": [
                              "user",
                              "organization"
                            ]
                          },
                          "user_collaborators": {
                            "type": "array",
                            "items": {
                              "type": "object",
                              "description": "A GitHub user",
                              "properties": {
                                "id": {
                                  "type": "integer",
                                  "format": "int64",
                                  "description": "The unique identifier of the user"
                                }
                              }
                            },
                            "description": "User objects of collaborators on this task",
                            "deprecated": true
                          },
                          "owner": {
                            "description": "The owner of the repository",
                            "type": "object",
                            "properties": {
                              "id": {
                                "type": "integer",
                                "format": "int64",
                                "description": "The unique identifier of the user"
                              }
                            }
                          },
                          "repository": {
                            "description": "The repository this task belongs to",
                            "type": "object",
                            "properties": {
                              "id": {
                                "type": "integer",
                                "format": "int64",
                                "description": "The unique identifier of the repository"
                              }
                            }
                          },
                          "state": {
                            "type": "string",
                            "description": "Current state of the task, derived from its most recent session",
                            "enum": [
                              "queued",
                              "in_progress",
                              "completed",
                              "failed",
                              "idle",
                              "waiting_for_user",
                              "timed_out",
                              "cancelled"
                            ]
                          },
                          "session_count": {
                            "type": "integer",
                            "format": "int32",
                            "description": "Number of sessions in this task"
                          },
                          "artifacts": {
                            "type": "array",
                            "items": {
                              "type": "object",
                              "description": "A resource generated by the task",
                              "required": [
                                "provider",
                                "type",
                                "data"
                              ],
                              "properties": {
                                "provider": {
                                  "type": "string",
                                  "enum": [
                                    "github"
                                  ],
                                  "description": "Provider namespace"
                                },
                                "type": {
                                  "type": "string",
                                  "enum": [
                                    "pull",
                                    "branch"
                                  ],
                                  "description": "Type of artifact. Available Values: `pull`, `branch`.\n"
                                },
                                "data": {
                                  "oneOf": [
                                    {
                                      "type": "object",
                                      "description": "A GitHub resource (pull request, issue, etc.)",
                                      "required": [
                                        "id"
                                      ],
                                      "properties": {
                                        "id": {
                                          "type": "integer",
                                          "format": "int64",
                                          "description": "GitHub resource ID"
                                        },
                                        "global_id": {
                                          "type": "string",
                                          "description": "GraphQL global ID"
                                        }
                                      }
                                    },
                                    {
                                      "type": "object",
                                      "description": "A Git branch reference",
                                      "required": [
                                        "head_ref",
                                        "base_ref"
                                      ],
                                      "properties": {
                                        "head_ref": {
                                          "type": "string",
                                          "description": "Head branch name"
                                        },
                                        "base_ref": {
                                          "type": "string",
                                          "description": "Base branch name"
                                        }
                                      }
                                    }
                                  ],
                                  "description": "Resource data (shape depends on type)"
                                }
                              }
                            },
                            "description": "Resources created by this task (PRs, branches, etc.)"
                          },
                          "archived_at": {
                            "type": "string",
                            "format": "date-time",
                            "nullable": true,
                            "description": "Timestamp when the task was archived, null if not archived"
                          },
                          "updated_at": {
                            "type": "string",
                            "format": "date-time",
                            "description": "Timestamp of the most recent update"
                          },
                          "created_at": {
                            "type": "string",
                            "format": "date-time",
                            "description": "Timestamp when the task was created"
                          },
                          "custom_agent": {
                            "type": "object",
                            "description": "Custom agent metadata associated with this task",
                            "properties": {
                              "id": {
                                "type": "string",
                                "description": "The custom agent's filename without the extension - for example, `performance-optimizer` for a `.github/agents/performance-optimizer.agent.md` custom agent."
                              }
                            }
                          }
                        }
                      },
                      "description": "Tasks created by the automation."
                    }
                  }
                },
                "examples": {
                  "default": {
                    "value": {
                      "tasks": [
                        {
                          "id": "b2c3d4e5-f6a7-8901-bcde-f23456789012",
                          "name": "Triage issue #42",
                          "creator": {
                            "id": 123
                          },
                          "creator_type": "user",
                          "repository": {
                            "id": 1296269
                          },
                          "state": "completed",
                          "session_count": 1,
                          "artifacts": [],
                          "archived_at": null,
                          "created_at": "2026-05-02T12:00:00Z",
                          "updated_at": "2026-05-02T12:05:00Z"
                        }
                      ]
                    }
                  }
                }
              }
            }
          },
