    "/agents/repos/{owner}/{repo}/automations": {
      "get": {
        "summary": "List automations for a repository",
        "description": "Returns a paginated list of the authenticated user's automations for a repository,\ntogether with every repository-owned automation in it. `total_count` is the number of\ncaller-visible automations matching the supplied filters across all pages.\nRepository-owned automations are visible to anyone with read access to the repository,\nso the results are not limited to automations the caller created. Use the `owner_type`\nfield on each automation to tell the two apart.\n\n**Fine-grained access tokens for \"List automations for a repository\"**\n\nThis endpoint works with the following fine-grained token types:\n\n* [GitHub App user access tokens](https://docs.github.com/en/apps/creating-github-apps/authenticating-with-a-github-app/generating-a-user-access-token-for-a-github-app)\n* [Fine-grained personal access tokens](https://docs.github.com/en/authentication/keeping-your-account-and-data-secure/managing-your-personal-access-tokens#creating-a-fine-grained-personal-access-token)\n\nThe fine-grained token must have one of the following permission sets for each\nrepository accessed by this request:\n\n* \"Agent tasks\" repository permissions (read)\n* \"Contents\" repository permissions (read)\n\nThe required permission set depends on each repository's Automation permission\nconfiguration.\n\nGitHub App installation access tokens are not supported for this endpoint.\n",
        "tags": [
          "agent-automations"
        ],
        "operationId": "agent-automations/list-repo-automations",
        "externalDocs": {
          "description": "API method documentation",
          "url": "https://docs.github.com/rest/agent-automations/agent-automations#list-automations-for-a-repository"
        },
        "x-github": {
          "githubCloudOnly": false,
          "enabledForGitHubApps": true,
          "category": "agent-automations",
          "subcategory": "agent-automations"
        },
        "parameters": [
          {
            "name": "owner",
            "in": "path",
            "required": true,
            "schema": {
              "type": "string"
            },
            "description": "The account owner of the repository. The name is not case sensitive."
          },
          {
            "name": "repo",
            "in": "path",
            "required": true,
            "schema": {
              "type": "string"
            },
            "description": "The name of the repository. The name is not case sensitive."
          },
          {
            "name": "page",
            "in": "query",
            "schema": {
              "type": "integer",
              "default": 1,
              "minimum": 1
            },
            "description": "The page number of the results to fetch."
          },
          {
            "name": "per_page",
            "in": "query",
            "schema": {
              "type": "integer",
              "default": 30,
              "minimum": 1,
              "maximum": 100
            },
            "description": "The number of results per page (max 100)."
          },
          {
            "name": "owner_type",
            "in": "query",
            "schema": {
              "type": "string",
              "enum": [
                "user",
                "repository"
              ]
            },
            "description": "Filter automations by owner type. `user` returns automations owned by their creator, `repository` returns automations owned by the repository. Omit to return both."
          }
        ],
        "responses": {
          "200": {
            "description": "Automations retrieved successfully",
            "headers": {
              "Link": {
                "description": "Pagination links",
                "schema": {
                  "type": "string"
                },
                "example": "<https://api.github.com/agents/repos/octo-org/octo-repo/automations?page=2&per_page=2>; rel=\"next\", <https://api.github.com/agents/repos/octo-org/octo-repo/automations?page=1&per_page=2>; rel=\"first\""
              }
            },
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "description": "A page of automations for a repository and the complete filtered result count.",
                  "required": [
                    "automations",
                    "total_count"
                  ],
                  "properties": {
                    "automations": {
                      "type": "array",
                      "items": {
                        "type": "object",
                        "description": "A summary representation of an automation (used in list responses).",
                        "required": [
                          "id",
                          "name",
                          "created_at",
                          "updated_at",
                          "created_by"
                        ],
                        "properties": {
                          "id": {
                            "type": "string",
                            "description": "The unique identifier of the automation."
                          },
                          "name": {
                            "type": "string",
                            "description": "The name of the automation."
                          },
                          "enabled": {
                            "type": "boolean",
                            "description": "Whether the automation is currently enabled."
                          },
                          "owner_type": {
                            "type": "string",
                            "enum": [
                              "user",
                              "repository"
                            ],
                            "description": "Who owns the automation. `user` keeps it private to its creator and its runs act as that user. `repository` makes it belong to the repository, visible to anyone with read access to the repository, and its runs act as the Copilot app rather than as a person.",
                            "readOnly": true
                          },
                          "write_scope": {
                            "type": "string",
                            "enum": [
                              "trigger",
                              "repository"
                            ],
                            "description": "Controls which repository resources a run may modify. `trigger` limits writes to the resource that started the run, when one exists, and resources created during the run; `repository` allows writes to any resource in the repository. Supported values: `trigger`, `repository`.",
                            "default": "trigger"
                          },
                          "require_actor_write_permission": {
                            "type": "boolean",
                            "description": "When true, event-triggered runs require the event actor to have repo write permission, even when the org's allow_read_access_triggers policy is enabled. Does not apply to interval-scheduled runs, which always run as the automation owner.",
                            "default": false
                          },
                          "model": {
                            "type": "string",
                            "description": "The model to use for sessions triggered by this automation. Omit to use the platform default."
                          },
                          "reasoning_effort": {
                            "type": "string",
                            "description": "The reasoning effort to use for sessions triggered by this automation. Omit or leave empty for no override. Currently supported values: `none`, `low`, `medium`, `high`, `xhigh`, `max`"
                          },
                          "triggers": {
                            "type": "object",
                            "additionalProperties": false,
                            "description": "Public trigger configuration keyed by stable public trigger identifier. Each trigger has a closed, trigger-specific configuration schema.",
                            "properties": {
                              "interval": {
                                "type": "object",
                                "additionalProperties": false,
                                "required": [
                                  "cadence"
                                ],
                                "properties": {
                                  "cadence": {
                                    "type": "array",
                                    "minItems": 1,
                                    "uniqueItems": true,
                                    "items": {
                                      "type": "string",
                                      "enum": [
                                        "hourly",
                                        "daily",
                                        "weekly"
                                      ]
                                    },
                                    "description": "One or more schedules on which the Automation runs."
                                  },
                                  "hour_utc": {
                                    "type": "integer",
                                    "minimum": 0,
                                    "maximum": 23,
                                    "description": "UTC hour anchor (0 through 23) for daily and weekly schedules. Omitted daily and weekly values default to `0` (midnight UTC)."
                                  },
                                  "day_of_week": {
                                    "type": "integer",
                                    "minimum": 0,
                                    "maximum": 6,
                                    "description": "UTC weekday anchor for weekly schedules, where `0` is Sunday and `6` is Saturday. Omitted weekly values default to Monday (`1`)."
                                  },
                                  "minute_utc": {
                                    "type": "integer",
                                    "enum": [
                                      0,
                                      15,
                                      30,
                                      45
                                    ],
                                    "default": 0,
                                    "description": "UTC minute anchor for daily and weekly schedules. Omitted daily and weekly values default to `0`. Must be omitted whenever `cadence` includes `hourly`."
                                  },
                                  "write_scope": {
                                    "type": "string",
                                    "enum": [
                                      "trigger",
                                      "repository"
                                    ],
                                    "description": "Override the Automation `write_scope` for runs started by this trigger. If omitted, the automation's `write_scope` is used. Organization or repository policy may restrict the effective scope to `trigger`."
                                  }
                                }
                              },
                              "issue_opened": {
                                "type": "object",
                                "additionalProperties": false,
                                "properties": {
                                  "query": {
                                    "type": "string",
                                    "minLength": 1,
                                    "description": "A GitHub issue or pull request search query."
                                  },
                                  "write_scope": {
                                    "type": "string",
                                    "enum": [
                                      "trigger",
                                      "repository"
                                    ],
                                    "description": "Override the Automation `write_scope` for runs started by this trigger. If omitted, the automation's `write_scope` is used. Organization or repository policy may restrict the effective scope to `trigger`."
                                  }
                                }
                              },
                              "issue_labeled": {
                                "type": "object",
                                "additionalProperties": false,
                                "properties": {
                                  "query": {
                                    "type": "string",
                                    "minLength": 1,
                                    "description": "A GitHub issue or pull request search query."
                                  },
                                  "labels": {
                                    "type": "array",
                                    "uniqueItems": true,
                                    "items": {
                                      "type": "string"
                                    },
                                    "description": "Label names matched case-insensitively against the label added by the event. Omit or use an empty array to match every added label."
                                  },
                                  "write_scope": {
                                    "type": "string",
                                    "enum": [
                                      "trigger",
                                      "repository"
                                    ],
                                    "description": "Override the Automation `write_scope` for runs started by this trigger. If omitted, the automation's `write_scope` is used. Organization or repository policy may restrict the effective scope to `trigger`."
                                  }
                                }
                              },
                              "workflow_run": {
                                "type": "object",
