    "/agents/repos/{owner}/{repo}/automations/{automation_id}": {
      "get": {
        "summary": "Get an automation for a repository",
        "description": "Returns an automation by ID in a repository.\n\nUser-owned automations are visible only to their creator. Repository-owned\nautomations are visible to anyone with read access to the repository. The\n`created_by` field identifies the creator and is distinct from the automation's\n`owner_type`.\n\n**Fine-grained access tokens for \"Get an automation for a repository\"**\n\nThis endpoint works with the following fine-grained token types:\n\n* [GitHub App user access tokens](https://docs.github.com/en/apps/creating-github-apps/authenticating-with-a-github-app/generating-a-user-access-token-for-a-github-app)\n* [Fine-grained personal access tokens](https://docs.github.com/en/authentication/keeping-your-account-and-data-secure/managing-your-personal-access-tokens#creating-a-fine-grained-personal-access-token)\n\nThe fine-grained token must have one of the following permission sets for each\nrepository accessed by this request:\n\n* \"Agent tasks\" repository permissions (read)\n* \"Contents\" repository permissions (read)\n\nThe required permission set depends on each repository's Automation permission\nconfiguration.\n\nGitHub App installation access tokens are not supported for this endpoint.\n",
        "tags": [
          "agent-automations"
        ],
        "operationId": "agent-automations/get-repo-automation",
        "externalDocs": {
          "description": "API method documentation",
          "url": "https://docs.github.com/rest/agent-automations/agent-automations#get-an-automation-for-a-repository"
        },
        "x-github": {
          "githubCloudOnly": false,
          "enabledForGitHubApps": true,
          "category": "agent-automations",
          "subcategory": "agent-automations"
        },
        "parameters": [
          {
            "name": "owner",
            "in": "path",
            "required": true,
            "schema": {
              "type": "string"
            },
            "description": "The account owner of the repository. The name is not case sensitive."
          },
          {
            "name": "repo",
            "in": "path",
            "required": true,
            "schema": {
              "type": "string"
            },
            "description": "The name of the repository. The name is not case sensitive."
          },
          {
            "name": "automation_id",
            "in": "path",
            "required": true,
            "schema": {
              "type": "string"
            },
            "description": "The unique identifier of the automation."
          }
        ],
        "responses": {
          "200": {
            "description": "Automation retrieved successfully",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "description": "A full representation of an automation including all configuration fields.",
                  "required": [
                    "id",
                    "name",
                    "prompt",
                    "created_at",
                    "updated_at",
                    "created_by"
                  ],
                  "properties": {
                    "id": {
                      "type": "string",
                      "description": "The unique identifier of the automation."
                    },
                    "name": {
                      "type": "string",
                      "description": "The name of the automation."
                    },
                    "enabled": {
                      "type": "boolean",
                      "description": "Whether the automation is currently enabled."
                    },
                    "owner_type": {
                      "type": "string",
                      "enum": [
                        "user",
                        "repository"
                      ],
                      "description": "Who owns the automation. `user` keeps it private to its creator and its runs act as that user. `repository` makes it belong to the repository, visible to anyone with read access to the repository, and its runs act as the Copilot app rather than as a person.",
                      "readOnly": true
                    },
                    "write_scope": {
                      "type": "string",
                      "enum": [
                        "trigger",
                        "repository"
                      ],
                      "description": "Controls which repository resources a run may modify. `trigger` limits writes to the resource that started the run, when one exists, and resources created during the run; `repository` allows writes to any resource in the repository. Supported values: `trigger`, `repository`.",
                      "default": "trigger"
                    },
                    "require_actor_write_permission": {
                      "type": "boolean",
                      "description": "When true, event-triggered runs require the event actor to have repo write permission, even when the org's allow_read_access_triggers policy is enabled. Does not apply to interval-scheduled runs, which always run as the automation owner.",
                      "default": false
                    },
                    "triggers": {
                      "type": "object",
                      "additionalProperties": false,
                      "description": "Public trigger configuration keyed by stable public trigger identifier. Each trigger has a closed, trigger-specific configuration schema.",
                      "properties": {
                        "interval": {
                          "type": "object",
                          "additionalProperties": false,
                          "required": [
                            "cadence"
                          ],
                          "properties": {
                            "cadence": {
                              "type": "array",
                              "minItems": 1,
                              "uniqueItems": true,
                              "items": {
                                "type": "string",
                                "enum": [
                                  "hourly",
                                  "daily",
                                  "weekly"
                                ]
                              },
                              "description": "One or more schedules on which the Automation runs."
                            },
                            "hour_utc": {
                              "type": "integer",
                              "minimum": 0,
                              "maximum": 23,
                              "description": "UTC hour anchor (0 through 23) for daily and weekly schedules. Omitted daily and weekly values default to `0` (midnight UTC)."
                            },
                            "day_of_week": {
                              "type": "integer",
                              "minimum": 0,
                              "maximum": 6,
                              "description": "UTC weekday anchor for weekly schedules, where `0` is Sunday and `6` is Saturday. Omitted weekly values default to Monday (`1`)."
                            },
                            "minute_utc": {
                              "type": "integer",
                              "enum": [
                                0,
                                15,
                                30,
                                45
