      "patch": {
        "summary": "Edit an automation for a repository",
        "description": "Edits specified fields on an existing automation in a repository. Omitted fields\nare left unchanged.\nThe automation's `owner_type` is immutable and cannot be changed by this operation.\n\n**Fine-grained access tokens for \"Edit an automation for a repository\"**\n\nThis endpoint works with the following fine-grained token types:\n\n* [GitHub App user access tokens](https://docs.github.com/en/apps/creating-github-apps/authenticating-with-a-github-app/generating-a-user-access-token-for-a-github-app)\n* [Fine-grained personal access tokens](https://docs.github.com/en/authentication/keeping-your-account-and-data-secure/managing-your-personal-access-tokens#creating-a-fine-grained-personal-access-token)\n\nThe fine-grained token must have one of the following permission sets for each\nrepository accessed by this request:\n\n* \"Agent tasks\" repository permissions (read and write)\n* \"Contents\" repository permissions (read and write)\n\nThe required permission set depends on each repository's Automation permission\nconfiguration.\n\nGitHub App installation access tokens are not supported for this endpoint.\n",
        "tags": [
          "agent-automations"
        ],
        "operationId": "agent-automations/edit-repo-automation",
        "externalDocs": {
          "description": "API method documentation",
          "url": "https://docs.github.com/rest/agent-automations/agent-automations#edit-an-automation-for-a-repository"
        },
        "x-github": {
          "githubCloudOnly": false,
          "enabledForGitHubApps": true,
          "category": "agent-automations",
          "subcategory": "agent-automations"
        },
        "parameters": [
          {
            "name": "owner",
            "in": "path",
            "required": true,
            "schema": {
              "type": "string"
            },
            "description": "The account owner of the repository. The name is not case sensitive."
          },
          {
            "name": "repo",
            "in": "path",
            "required": true,
            "schema": {
              "type": "string"
            },
            "description": "The name of the repository. The name is not case sensitive."
          },
          {
            "name": "automation_id",
            "in": "path",
            "required": true,
            "schema": {
              "type": "string"
            },
            "description": "The unique identifier of the automation."
          }
        ],
        "requestBody": {
          "required": true,
          "description": "The automation fields to update. Omitted fields are left unchanged.",
          "content": {
            "application/json": {
              "schema": {
                "type": "object",
                "description": "Request body for editing an automation. Omitted fields are left unchanged. Explicit null values are rejected.",
                "properties": {
                  "name": {
                    "type": "string",
                    "description": "The name of the automation."
                  },
                  "enabled": {
                    "type": "boolean",
                    "description": "Set to true to enable, false to disable. Omit to leave unchanged."
                  },
                  "write_scope": {
                    "type": "string",
                    "enum": [
                      "trigger",
                      "repository"
                    ],
                    "description": "Controls which repository resources a run may modify. `trigger` limits writes to the resource that started the run, when one exists, and resources created during the run; `repository` allows writes to any resource in the repository. Supported values: `trigger`, `repository`. Omit to leave unchanged."
                  },
                  "require_actor_write_permission": {
                    "type": "boolean",
                    "description": "When true, event-triggered runs require the event actor to have repo write permission, even when the org's allow_read_access_triggers policy is enabled. Does not apply to interval-scheduled runs, which always run as the automation owner. Omit to leave unchanged."
                  },
                  "model": {
                    "type": "string",
                    "description": "The model to use for sessions triggered by this automation. Omit to leave unchanged. Send an empty string to clear the model and revert to the platform default."
                  },
                  "reasoning_effort": {
                    "description": "The reasoning effort to use for sessions triggered by this automation. Omit to leave unchanged. Send an empty string to clear the override. Currently supported values: `none`, `low`, `medium`, `high`, `xhigh`, `max`",
                    "oneOf": [
                      {
                        "type": "string",
                        "maxLength": 0
                      },
                      {
                        "type": "string",
                        "enum": [
                          "none",
                          "low",
                          "medium",
                          "high",
                          "xhigh",
                          "max"
                        ]
                      }
                    ]
                  },
                  "triggers": {
                    "type": "object",
                    "additionalProperties": false,
                    "description": "Public trigger configuration keyed by stable public trigger identifier. Each trigger has a closed, trigger-specific configuration schema.",
                    "properties": {
                      "interval": {
                        "type": "object",
                        "additionalProperties": false,
                        "required": [
                          "cadence"
                        ],
                        "properties": {
                          "cadence": {
                            "type": "array",
                            "minItems": 1,
                            "uniqueItems": true,
                            "items": {
                              "type": "string",
                              "enum": [
                                "hourly",
                                "daily",
                                "weekly"
                              ]
                            },
                            "description": "One or more schedules on which the Automation runs."
                          },
                          "hour_utc": {
                            "type": "integer",
                            "minimum": 0,
                            "maximum": 23,
                            "description": "UTC hour anchor (0 through 23) for daily and weekly schedules. Omitted daily and weekly values default to `0` (midnight UTC)."
                          },
                          "day_of_week": {
                            "type": "integer",
                            "minimum": 0,
                            "maximum": 6,
                            "description": "UTC weekday anchor for weekly schedules, where `0` is Sunday and `6` is Saturday. Omitted weekly values default to Monday (`1`)."
                          },
                          "minute_utc": {
                            "type": "integer",
                            "enum": [
                              0,
                              15,
                              30,
                              45
                            ],
                            "default": 0,
                            "description": "UTC minute anchor for daily and weekly schedules. Omitted daily and weekly values default to `0`. Must be omitted whenever `cadence` includes `hourly`."
                          },
                          "write_scope": {
                            "type": "string",
