    "/orgs/{org}/projectsV2/{project_number}/views": {
      "post": {
        "summary": "Create a view for an organization-owned project",
        "description": "Create a new view in an organization-owned project. Views allow you to customize how items in a project are displayed and filtered.",
        "tags": [
          "projects"
        ],
        "operationId": "projects/create-view-for-org",
        "externalDocs": {
          "description": "API method documentation",
          "url": "https://docs.github.com/rest/projects/views#create-a-view-for-an-organization-owned-project"
        },
