    "/repos/{owner}/{repo}/pulls/{pull_number}/merge-async": {
      "put": {
        "summary": "Merge a pull request asynchronously",
        "description": "Merges a pull request into the base branch in the background or adds it to a merge queue. Background processing allows certain types of errors to be retried and reduces the risk of timeouts for complex merges.\n\nThis is the required API for merging stacked pull requests. For a stacked pull request, the operation includes all open downstack pull requests.\n\nA new asynchronous merge request returns a `202` response with a UUID that can be used to [fetch the result of the merge](https://docs.github.com/rest/pulls/pulls#get-the-result-of-an-asynchronous-merge). If another asynchronous merge request is already pending for this pull request, a `409` response returns that request's UUID and merge options instead.\n\nIf the pull request is already merged or already in a merge queue, a `200` response is returned immediately. A `merged` result includes the merge commit OID. An `enqueued` result means the pull request was added to the merge queue, not that it has merged.\n\nIf the pull request cannot be merged (e.g. because it is closed, or still a draft) this result will be returned immediately with a `400` response status. Branch protection rules and repository rules are not run at this stage, only basic pull request state checks are performed.",
        "tags": [
          "pulls"
        ],
        "operationId": "pulls/merge-async",
        "externalDocs": {
          "description": "API method documentation",
