            "nullable": true
          },
          "target_value": {
            "description": "The proposed value, when applicable. An array for multi-select field suggestions.",
            "nullable": true,
            "oneOf": [
              {
                "type": "string"
              },
              {
                "type": "number"
              },
              {
                "type": "boolean"
